'use client';
import {useState,useEffect,useRef,useCallback,type ReactNode,type FormEvent} from 'react';
import {LayoutDashboard,CalendarDays,Lightbulb,Handshake,MessageSquareText,UserRound,ShieldCheck,ArrowUpRight,ArrowRight,ArrowLeft,Plus,Search,MapPin,Clock3,Video,Bookmark,ChevronDown,ChevronRight,Check,CheckCircle2,X,Menu,LockKeyhole,ExternalLink,Download,RefreshCw,Users,Target,Radio,Trophy,ThumbsUp,Send,Settings2,ClipboardCheck,Mail,BriefcaseBusiness,Sparkles,FileText,LogOut,LoaderCircle,Wifi,CalendarCheck,Heart,Flag,Upload,LogIn,BookOpen} from 'lucide-react';
import type {PlatformState,Session,Project,Connection,Opportunity,Question} from './lib/types';
import {categories,rubric} from './lib/programme';
import AttendancePanel,{type CounterStatus} from './AttendancePanel';
import {Tag,SignInPanel,Empty,Field,Dialog} from './ui';
